def _decode(table: Dict[int, Dict[int, str]], data: bytes) -> str:
    by_code = {prior: {code: sym for sym, code in codes.items()} for prior, codes in table.items()}
    bits = "".join(f"{byte:08b}" for byte in data)
    prior = 0
    out = []
    i = 0
    n = len(bits)
    while i < n:
        codes = by_code.get(prior) or {}
        matched = None
        end = None
        for j in range(i + 1, n + 1):
            hit = codes.get(bits[i:j])
            if hit is not None:
                matched = hit
                end = j
                break
        if matched is None or end is None:
            break
        i = end
        if matched == 0:
            break
        if matched == 27:
            if i + 8 > n:
                break
            ch = int(bits[i:i + 8], 2)
            i += 8
            if ch == 0:
                break
            out.append(chr(ch))
            prior = ch
            continue
        out.append(chr(matched))
        prior = matched
    return "".join(out)


def decode_title(data: bytes) -> str:
    return _decode(TITLE, data)


def decode_description(data: bytes) -> str:
    return _decode(DESCRIPTION, data)


def encode(table: Dict[int, Dict[int, str]], text: str) -> bytes:
    prior = 0
    bits = ""
    for ch in text:
        sym = ord(ch) & 0xFF
        codes = table.get(prior) or {}
        code = codes.get(sym)
        if code is None:
            bits += codes[27] + f"{sym:08b}"
        else:
            bits += code
        prior = sym
    bits += table[prior][0]
    while len(bits) % 8:
        bits += "0"
    return bytes(int(bits[i:i + 8], 2) for i in range(0, len(bits), 8))
